.daily-board{grid-template-columns:1.2fr .8fr;gap:0;border-top:1px solid #3b3831;border-bottom:1px solid #3b3831}.daily-line,.daily-pick{border:0;border-radius:0;background:transparent!important;min-height:310px}.daily-line{padding:38px 36px 34px 0}.daily-line blockquote{font-size:clamp(30px,4vw,50px);font-family:Georgia,"Times New Roman",serif;font-weight:600}.daily-pick{border-left:1px solid #3b3831}.daily-pick>div{padding:32px}.daily-pick h3{font-size:26px}
